{
  "contents": "#!/usr/bin/env python3\n\"\"\"\nDIR-AN-SUB-A-RECALIBRATION-094 \u2014 Step 3: Brush Applicator Pristine Relighting\nNormalizes `assets/brands/COSRX/layers/08b_accessory_brush_applicator.png` into a\nproduction-ready studio-lit asset:\n  1. +0.45 EV linear exposure lift (eliminates dim flat-gray silicone/acrylic cast)\n  2. Warm morning daylight white-balance shift (~5400K)\n  3. Crisp white-silver Rim Light along the sunlit upper-left contour & vertical spine\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\nimport numpy as np\nfrom PIL import Image, ImageFilter\n\nREPO_ROOT = Path(__file__).resolve().parent.parent\nBRUSH_PATH = REPO_ROOT / \"assets\" / \"brands\" / \"COSRX\" / \"layers\" / \"08b_accessory_brush_applicator.png\"\n\n\ndef srgb_to_lin(x: np.ndarray) -> np.ndarray:\n    return np.where(x <= 0.04045, x / 12.92, ((x + 0.055) / 1.055) ** 2.4)\n\n\ndef lin_to_srgb(x: np.ndarray) -> np.ndarray:\n    x = np.clip(x, 0.0, 1.0)\n    return np.where(x <= 0.0031308, x * 12.92, 1.055 * (x ** (1.0 / 2.4)) - 0.055)\n\n\ndef relight_brush() -> None:\n    assert BRUSH_PATH.exists(), f\"Missing brush layer: {BRUSH_PATH}\"\n    im = Image.open(BRUSH_PATH).convert(\"RGBA\")\n    arr = np.array(im, dtype=np.float32) / 255.0\n    rgb = arr[..., :3]\n    alpha = arr[..., 3]\n    fg = alpha > 0.5\n\n    before_lum = float((0.299 * rgb[..., 0][fg] + 0.587 * rgb[..., 1][fg] + 0.114 * rgb[..., 2][fg]).mean() * 255.0)\n\n    # 1. Convert to linear light & apply +0.45 EV exposure lift (2^0.45 = 1.3660) + gentle highlight bloom\n    lin = srgb_to_lin(rgb)\n    ev_gain = float(2.0 ** 0.45)\n    lin = lin * ev_gain\n\n    # 2. Warm morning light white balance (~5400K) to remove cool gray tint\n    wb_5400k = np.array([1.055, 1.012, 0.945], dtype=np.float32)[None, None, :]\n    lin = lin * wb_5400k\n\n    # Subtle lift on mid-shadows of the silicone paddle (top 30% of height) so it reads luminous pearl-silver\n    h, w = alpha.shape\n    ys, xs = np.where(fg)\n    y0, y1 = int(ys.min()), int(ys.max())\n    x0, x1 = int(xs.min()), int(xs.max())\n    bh = max(1, y1 - y0)\n    bw = max(1, x1 - x0)\n\n    yy, xx = np.indices((h, w), dtype=np.float32)\n    yn = np.clip((yy - y0) / bh, 0.0, 1.0)\n    xn = (xx - (x0 + x1) * 0.5) / (bw * 0.5)\n\n    # Gentle soft highlight dome on silicone head (yn < 0.28)\n    head_mask = np.clip(1.0 - (yn - 0.22) / 0.12, 0.0, 1.0)\n    head_spec = head_mask * np.exp(-(((xn + 0.28) / 0.48) ** 2)) * 0.16\n\n    # 3. Crisp bright white-silver Rim Light along sunlit left contour + sleek specular spine on handle/ferrule\n    a_img = Image.fromarray(np.round(alpha * 255.0).astype(np.uint8), mode=\"L\")\n    a_eroded = np.array(a_img.filter(ImageFilter.MinFilter(size=9)), dtype=np.float32) / 255.0\n    a_blur = np.array(a_img.filter(ImageFilter.GaussianBlur(radius=3.5)), dtype=np.float32) / 255.0\n\n    # Directional gradient of alpha to isolate top-left sunlit rim\n    gx = np.zeros_like(a_blur)\n    gy = np.zeros_like(a_blur)\n    gx[:, 1:-1] = (a_blur[:, 2:] - a_blur[:, :-2]) * 0.5\n    gy[1:-1, :] = (a_blur[2:, :] - a_blur[:-2, :]) * 0.5\n    # Outward normal points (-gx, -gy); key light from top-left (-0.75, -0.55)\n    rim_dir = np.clip((-gx * -0.82) + (-gy * -0.45), 0.0, 1.0)\n    rim_band = np.clip((alpha - a_eroded) * 2.2, 0.0, 1.0)\n    rim_light = rim_band * np.clip(rim_dir * 4.5, 0.0, 1.0) * 0.42\n\n    # Slender specular highlight line running vertically along the sunlit left-center spine of ferrule & acrylic handle\n    spine_zone = np.clip((yn - 0.23) / 0.08, 0.0, 1.0) * np.clip((0.97 - yn) / 0.06, 0.0, 1.0)\n    spine_streak = spine_zone * np.exp(-(((xn + 0.16) / 0.085) ** 2)) * 0.32\n\n    silver_white = np.array([1.00, 0.99, 0.96], dtype=np.float32)[None, None, :]\n    lin = lin + (head_spec + rim_light + spine_streak)[..., None] * silver_white\n\n    # Smooth highlight roll-off (preserve specular detail without harsh flat clipping)\n    lin_mapped = lin / (1.0 + lin * 0.06)\n    srgb_out = lin_to_srgb(lin_mapped)\n\n    after_lum = float((0.299 * srgb_out[..., 0][fg] + 0.587 * srgb_out[..., 1][fg] + 0.114 * srgb_out[..., 2][fg]).mean() * 255.0)\n\n    out_rgba = np.zeros((h, w, 4), dtype=np.uint8)\n    out_rgba[..., :3] = np.clip(np.round(srgb_out * 255.0), 0, 255).astype(np.uint8)\n    out_rgba[..., 3] = np.clip(np.round(alpha * 255.0), 0, 255).astype(np.uint8)\n    out_rgba[out_rgba[..., 3] == 0] = 0\n\n    Image.fromarray(out_rgba, mode=\"RGBA\").save(BRUSH_PATH, \"PNG\")\n    print(\n        f\"[RELIGHT_BRUSH] Saved pristine relit brush: {BRUSH_PATH} ({w}x{h} RGBA) | \"\n        f\"mean_luma: {before_lum:.1f} -> {after_lum:.1f} (+{after_lum - before_lum:.1f})\"\n    )\n\n\nif __name__ == \"__main__\":\n    relight_brush()\n",
  "timestamp": 1795798689954
}